func TestStatusFilterString(t *testing.T) {
	f := proto.StatusFilter{}
	expect := ""
	got := f.String()
	if got != expect {
		t.Errorf("got '%s', expected '%s'", got, expect)
	}

	f = proto.StatusFilter{RequestId: "abc"}
	expect = "?requestId=abc"
	got = f.String()
	if got != expect {
		t.Errorf("got '%s', expected '%s'", got, expect)
	}

	f = proto.StatusFilter{RequestId: "abc", OrderBy: "startTime"}
	expect = "?requestId=abc&orderBy=starttime"
	got = f.String()
	if got != expect {
		t.Errorf("got '%s', expected '%s'", got, expect)
	}
}

func TestRequestFilterString(t *testing.T) {
	f := proto.RequestFilter{}
	expect := ""
	got := f.String()
	if got != expect {
		t.Errorf("got '%s', expected '%s'", got, expect)
	}

	f = proto.RequestFilter{
		Type: "request-type",
		States: []byte{
			proto.STATE_PENDING,
			proto.STATE_RUNNING,
			proto.STATE_SUSPENDED,
		},
		Args: map[string]string{
			"arg1": "val1",
			"arg2": "val2",
		},
		User:   "felixp",
		Since:  time.Date(2020, 01, 01, 12, 34, 56, 789123000, time.UTC),
		Until:  time.Date(2020, 01, 02, 12, 34, 56, 789000000, time.UTC),
		Limit:  5,
		Offset: 10,
	}
	expect = "arg=arg1%3Dval1&arg=arg2%3Dval2&limit=5&offset=10&since=2020-01-01T12%3A34%3A56.789123Z&state=PENDING&state=RUNNING&state=SUSPENDED&type=request-type&until=2020-01-02T12%3A34%3A56.789Z&user=felixp"
	got = f.String()
	if got != expect {
		t.Errorf("got '%s', expected '%s'", got, expect)
	}
}

